import sys
import math

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    s = input[1]
    v_positions = []
    k_positions = []
    other_positions = []

    for i, c in enumerate(s):
        if c == 'V':
            v_positions.append(i)
        elif c == 'K':
            k_positions.append(i)
        else:
            other_positions.append(i)

    naV = len(v_positions)
    naK = len(k_positions)
    naO = len(other_positions)

    INF = float('inf')
    # Initialize 4D DP array
    dp = [[[[INF for _ in range(2)] for _ in range(naO + 1)] for _ in range(naK + 1)] for _ in range(naV + 1)]
    dp[0][0][0][1] = 0

    arrs = [
        v_positions,
        k_positions,
        other_positions
    ]

    p = [[[0 for _ in range(n)] for _ in range(3)] for _ in range(3)]
    for x in range(3):
        for y in range(3):
            if x != y:
                for i in range(len(arrs[x])):
                    for j in range(len(arrs[y])):
                        if arrs[y][j] < arrs[x][i]:
                            p[x][y][i] += 1

    for i in range(naV + 1):
        for j in range(naK + 1):
            for k in range(naO + 1):
                for q in range(2):
                    if dp[i][j][k][q] != INF:
                        if i < naV:
                            cost = dp[i][j][k][q] + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0)
                            if cost < dp[i + 1][j][k][0]:
                                dp[i + 1][j][k][0] = cost
                        if j < naK and q == 1:
                            cost = dp[i][j][k][q] + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0)
                            if cost < dp[i][j + 1][k][1]:
                                dp[i][j + 1][k][1] = cost
                        if k < naO:
                            cost = dp[i][j][k][q] + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0)
                            if cost < dp[i][j][k + 1][1]:
                                dp[i][j][k + 1][1] = cost

    print(min(dp[naV][naK][naO][0], dp[naV][naK][naO][1]))

